const best = new Promise((resolve) => {
  for (const score of [7, 9, 4]) {
    resolve(score);
  }
});
best.then((score) => console.log("score " + score));

const shop = new Promise((resolve, reject) => {
  reject(new Error("closed"));
  resolve("open");
});
shop.catch((error) => console.log("shop " + error.message));
